import imp
import importlib
from typing import Dict, Optional

_CACHE: Dict[str, object] = {}


def load(name: str) -> Optional[object]:
    try:
        module = importlib.import_module(name)
    except ImportError:
        return None
    _CACHE[name] = module
    return module


def reload(name: str) -> Optional[object]:
    module = _CACHE.get(name)
    if module is None:
        return None
    return imp.reload(module)

