import unittest
from datetime import datetime

from plugins.clock import stamp


class StampTest(unittest.TestCase):
    def test_parses_back(self):
        self.assertEquals(type(datetime.fromisoformat(stamp())), datetime)

    def test_has_no_offset(self):
        self.assertNotEquals(stamp()[-6:-5], "+")
